#!/usr/bin/env python3
"""agent-tasks — a Herdr pane showing the agent-workflow task board.

Renders every project board from the agent-workflow control plane, lets you
create tasks and cycle statuses in place, and toggles itself open/focused/closed
via Herdr's plugin-pane API.

Modes:
  (default)   run the TUI in a Herdr pane
  --toggle    open / focus / close this plugin's pane
  --list      plain-text listing (for scripts/tests)
  --json      machine-readable listing (for scripts/tests)
"""

from __future__ import annotations

import curses
import json
import os
import re
import socket
import subprocess
import sys
import time
from pathlib import Path

SOURCE = "agent-tasks"
TITLE = "Tasks"
STATUSES = ["todo", "claimed", "writing", "review", "blocked", "done"]


def workflow_dir() -> Path:
    env = os.environ.get("AGENT_WORKFLOW_DIR")
    if env:
        return Path(env)
    root = os.environ.get("HERDR_PLUGIN_ROOT")
    if root:
        return Path(root).resolve().parent
    return Path("/home/agentops/dev/agent-workflow")


WF = workflow_dir()
sys.path.insert(0, str(WF / "runner"))
import board as boardmod  # noqa: E402


# --------------------------------------------------------------------------- #
# Data access (reuses the tested deterministic parser in runner/board.py)
# --------------------------------------------------------------------------- #
def load_all() -> list:
    tasks = boardmod.load_tasks(None, None)
    tasks.sort(key=lambda t: (t.project or "~", boardmod._natkey(t.id)))
    return tasks


def board_path(project: str) -> Path:
    return WF / "tasks" / f"{project}.md"


def next_id(project: str) -> str:
    nums = []
    for t in boardmod.load_tasks(project, None):
        if t.project == project and t.id.isdigit():
            nums.append(int(t.id))
    return f"{(max(nums) + 1) if nums else 1:02d}"


def create_task(project: str, title: str, seam: str, deps: str, risk: str, description: str) -> str:
    path = board_path(project)
    if not path.exists():
        raise SystemExit(f"no board for project {project!r}: {path}")
    tid = next_id(project)
    deps = (deps or "none").strip() or "none"
    risk = (risk or "none").strip() or "none"
    body = "\n".join("    " + line if line.strip() else "" for line in (description or title).splitlines())
    block = (
        f"\n## [{tid}] {title}\n"
        f"project: {project}\n"
        f"seam: {seam}\n"
        f"deps: {deps}\n"
        f"risk: {risk}\n"
        f"status: todo\n"
        f"description: |\n{body}\n"
    )
    with path.open("a") as fh:
        fh.write(block)
    return tid


def cycle_status(task) -> str:
    cur = task.status if task.status in STATUSES else "todo"
    nxt = STATUSES[(STATUSES.index(cur) + 1) % len(STATUSES)]
    boardmod.set_status(task, nxt)
    return nxt


# --------------------------------------------------------------------------- #
# Herdr socket / pane plumbing
# --------------------------------------------------------------------------- #
def herdr_bin() -> str:
    return os.environ.get("HERDR_BIN_PATH", "herdr")


def herdr_call(method: str, params: dict) -> bool:
    path = os.environ.get("HERDR_SOCKET_PATH")
    if not path:
        return False
    try:
        s = socket.socket(socket.AF_UNIX, socket.SOCK_STREAM)
        s.settimeout(2)
        s.connect(path)
        s.sendall((json.dumps({"id": f"{SOURCE}:{method}", "method": method, "params": params}) + "\n").encode())
        data = b""
        while not data.endswith(b"\n"):
            chunk = s.recv(65536)
            if not chunk:
                break
            data += chunk
        s.close()
        resp = json.loads(data.decode() or "{}")
        return not resp.get("error")
    except OSError:
        return False


def stamp_heartbeat() -> None:
    pane = os.environ.get("HERDR_PANE_ID")
    if pane:
        herdr_call("pane.report_metadata", {
            "pane_id": pane, "source": SOURCE, "title": TITLE,
            "tokens": {SOURCE: str(int(time.time()))},
        })


def list_panes() -> list:
    ws = os.environ.get("HERDR_WORKSPACE_ID")
    cmd = [herdr_bin(), "pane", "list"]
    if ws:
        cmd += ["--workspace", ws]
    try:
        out = subprocess.check_output(cmd, text=True)
    except (OSError, subprocess.CalledProcessError):
        return []
    try:
        return json.loads(out).get("result", {}).get("panes", [])
    except json.JSONDecodeError:
        return []


def is_ours(p: dict) -> bool:
    return SOURCE in (p.get("tokens") or {})


def toggle() -> int:
    panes = list_panes()
    ours = [p for p in panes if is_ours(p)]
    focused = next((p for p in panes if p.get("focused")), None)
    if ours:
        target = ours[0]
        for extra in ours[1:]:
            subprocess.run([herdr_bin(), "plugin", "pane", "close", extra["pane_id"]], check=False)
        if focused and target["pane_id"] == focused.get("pane_id"):
            subprocess.run([herdr_bin(), "plugin", "pane", "close", target["pane_id"]], check=False)
        else:
            subprocess.run([herdr_bin(), "plugin", "pane", "focus", target["pane_id"]], check=False)
        return 0
    ws = os.environ.get("HERDR_WORKSPACE_ID")
    direction = os.environ.get("AGENT_TASKS_DIRECTION", "right")
    cmd = [herdr_bin(), "plugin", "pane", "open", "--plugin", SOURCE, "--entrypoint", "tasks",
           "--placement", "split", "--direction", direction, "--focus"]
    if ws:
        cmd += ["--workspace", ws]
    return subprocess.run(cmd, check=False).returncode


# --------------------------------------------------------------------------- #
# Plain output
# --------------------------------------------------------------------------- #
def render_plain(tasks) -> str:
    lines = []
    project = None
    for t in tasks:
        if t.project != project:
            project = t.project
            lines.append(f"\n== {project} ==")
        lines.append(f"[{t.id}] {t.title}  ({t.status}{', risk ' + t.fields['risk'] if t.is_risky else ''})")
    return "\n".join(lines).strip() or "(no tasks)"


# --------------------------------------------------------------------------- #
# TUI
# --------------------------------------------------------------------------- #
def init_colors() -> dict:
    curses.start_color()
    try:
        curses.use_default_colors()
    except curses.error:
        pass
    pairs = {
        "todo": (curses.COLOR_CYAN, -1),
        "claimed": (curses.COLOR_MAGENTA, -1),
        "writing": (curses.COLOR_YELLOW, -1),
        "review": (curses.COLOR_GREEN, -1),
        "blocked": (curses.COLOR_RED, -1),
        "done": (curses.COLOR_BLUE, -1),
    }
    out = {}
    for i, (name, (fg, bg)) in enumerate(pairs.items(), start=1):
        curses.init_pair(i, fg, bg)
        out[name] = curses.color_pair(i)
    return out


def draw(stdscr, tasks, selected, colors, message) -> None:
    stdscr.erase()
    h, w = stdscr.getmaxyx()
    todo = sum(1 for t in tasks if t.status == "todo")
    header = f" Agent Tasks — {todo} todo / {len(tasks)} total "
    stdscr.addnstr(0, 0, header.ljust(w)[:w], w, curses.A_REVERSE | curses.A_BOLD)

    rows = []
    project = None
    for idx, t in enumerate(tasks):
        if t.project != project:
            project = t.project
            rows.append(("header", None, project))
        rows.append(("task", idx, t))

    for r, (kind, idx, payload) in enumerate(rows, start=1):
        if r >= h - 2:
            break
        if kind == "header":
            stdscr.addnstr(r, 0, f" ▸ {payload}", w, curses.A_BOLD)
            continue
        t = payload
        sel = idx == selected
        risk = " !" if t.is_risky else ""
        text = f" [{t.id}] {t.title}{risk}"
        attr = colors.get(t.status, 0)
        if sel:
            attr |= curses.A_REVERSE
        stdscr.addnstr(r, 2, text.ljust(max(w - 14, 0))[: max(w - 2, 0)], w - 2, attr)
        stdscr.addnstr(r, max(w - 11, 0), f"{t.status:>9} ", 11, attr)

    if message:
        stdscr.addnstr(h - 2, 0, (" " + message)[:w], w, curses.A_BOLD)
    stdscr.addnstr(h - 1, 0, " n new  s status  e edit board  r refresh  q quit ", w, curses.A_DIM)
    stdscr.refresh()


def read_line(stdscr, row, prompt, default="") -> str | None:
    h, w = stdscr.getmaxyx()
    label = f"{prompt} [{default}]: " if default else f"{prompt}: "
    stdscr.addnstr(row, 0, label[:w], w)
    stdscr.refresh()
    try:
        raw = stdscr.getstr(row, min(len(label), max(w - 2, 0)), max(w - len(label) - 1, 1))
    except curses.error:
        return None
    val = raw.decode(errors="replace").strip()
    return val or default


def new_task_form(stdscr, projects) -> str | None:
    h, _ = stdscr.getmaxyx()
    stdscr.erase()
    stdscr.addnstr(0, 0, " New task (empty = default; Ctrl+C cancels)", 200, curses.A_REVERSE)
    stdscr.refresh()
    try:
        project = read_line(stdscr, 2, "project", projects[0] if projects else "")
        if project not in projects:
            return f"unknown project {project!r}"
        title = read_line(stdscr, 3, "title")
        if not title:
            return "cancelled: title required"
        seam = read_line(stdscr, 4, "seam (comma list)", "")
        if not seam:
            return "cancelled: seam required"
        deps = read_line(stdscr, 5, "deps (none)", "none")
        risk = read_line(stdscr, 6, "risk (none|high|critical)", "none")
        desc = read_line(stdscr, 7, "description", title)
    except KeyboardInterrupt:
        return "cancelled"
    try:
        tid = create_task(project, title, seam, deps, risk, desc)
    except SystemExit as exc:
        return str(exc)
    return f"created [{tid}] {title} in {project}"


def run_tui(stdscr) -> None:
    curses.curs_set(0)
    stdscr.keypad(True)
    colors = init_colors()
    selected = 0
    message = ""
    last_stamp = 0.0
    while True:
        tasks = load_all()
        if not tasks:
            selected = 0
        selected = max(0, min(selected, len(tasks) - 1))
        draw(stdscr, tasks, selected, colors, message)
        message = ""
        now = time.time()
        if now - last_stamp > 5:
            stamp_heartbeat()
            last_stamp = now
        stdscr.timeout(2000)
        ch = stdscr.getch()
        if ch == -1:
            continue
        if ch in (ord("q"), 27):
            return
        if ch in (curses.KEY_DOWN, ord("j")):
            selected = min(selected + 1, len(tasks) - 1)
        elif ch in (curses.KEY_UP, ord("k")):
            selected = max(selected - 1, 0)
        elif ch == ord("r"):
            continue
        elif ch == ord("s") and tasks:
            message = f"[{tasks[selected].id}] -> {cycle_status(tasks[selected])}"
        elif ch == ord("n"):
            projects = [p for p in boardmod.load_registry() if p != "defaults"]
            message = new_task_form(stdscr, projects) or "done"
        elif ch == ord("e") and tasks:
            open_in_editor(stdscr, Path(tasks[selected].source))


def open_in_editor(stdscr, path: Path) -> None:
    editor = os.environ.get("EDITOR") or "nano"
    curses.def_prog_mode()
    curses.endwin()
    try:
        subprocess.run([editor, str(path)], check=False)
    finally:
        curses.reset_prog_mode()
        stdscr.refresh()


def main() -> int:
    args = sys.argv[1:]
    if "--toggle" in args:
        return toggle()
    if "--list" in args:
        print(render_plain(load_all()))
        return 0
    if "--json" in args:
        print(json.dumps([t.to_dict() for t in load_all()], indent=2))
        return 0
    stamp_heartbeat()
    curses.wrapper(run_tui)
    return 0


if __name__ == "__main__":
    sys.exit(main())

